import React, { useCallback, useEffect, useState } from 'react'
import {
  Button,
  Card,
  Col,
  Divider,
  Drawer,
  message,
  Row,
  Spin,
  Typography,
  Modal,
  Tag,
  Space,
} from 'antd'
import {
  DownloadOutlined,
  SettingOutlined,
  AppstoreOutlined,
  SwapOutlined,
  CheckCircleOutlined,
} from '@ant-design/icons'
import service from '@/utils/api'
import useLocale from '@/hooks/useLocale'
import ThemeConfigPanel from './components/ThemeConfigPanel'
import styles from './style.module.less'

const { Title, Text } = Typography

interface BuiltinTheme {
  id: string
  name: string
  description: string
  author: string
  themeDir: string
}

interface ThemeStatus {
  installed: boolean
  isCurrent?: boolean
}

interface InstalledTheme {
  id: string
  name: string
  themeDir: string
  hasConfig: boolean
  builtin: boolean
  themeInfo: BuiltinTheme | null
}

const ThemeMarketPage: React.FC = () => {
  const t = useLocale()
  const [themes, setThemes] = useState<BuiltinTheme[]>([])
  const [statusMap, setStatusMap] = useState<Record<string, ThemeStatus>>({})
  const [installedThemes, setInstalledThemes] = useState<InstalledTheme[]>([])
  const [currentTheme, setCurrentTheme] = useState<string>('')
  const [loading, setLoading] = useState(true)
  const [installing, setInstalling] = useState<string | null>(null)
  const [switching, setSwitching] = useState<string | null>(null)
  const [switchModalVisible, setSwitchModalVisible] = useState(false)
  const [configModal, setConfigModal] = useState<{
    visible: boolean
    themeId: string
    themeName: string
  }>({ visible: false, themeId: '', themeName: '' })

  const fetchThemes = useCallback(async () => {
    try {
      const res = await service.get('/hexopro/api/theme/list')
      setThemes(res.data || [])
    } catch (err) {
      message.error(t['theme.list.fetchFailed'] || '获取主题列表失败')
    }
  }, [t])

  const fetchInstalledStatus = useCallback(async () => {
    if (themes.length === 0) return
    const map: Record<string, ThemeStatus> = {}
    await Promise.all(
      themes.map(async (theme) => {
        try {
          const res = await service.get('/hexopro/api/theme/installed', {
            params: { themeId: theme.id },
          })
          map[theme.id] = res.data || { installed: false }
        } catch {
          map[theme.id] = { installed: false }
        }
      })
    )
    setStatusMap(map)
  }, [themes])

  // 获取已安装的主题列表
  const fetchInstalledThemes = useCallback(async () => {
    try {
      const res = await service.get('/hexopro/api/theme/installed-list')
      if (res.data) {
        setInstalledThemes(res.data.themes || [])
        setCurrentTheme(res.data.currentTheme || '')
      }
    } catch (err) {
      console.error('获取已安装主题列表失败:', err)
    }
  }, [])

  useEffect(() => {
    const load = async () => {
      setLoading(true)
      await fetchThemes()
      setLoading(false)
    }
    void load()
  }, [fetchThemes])

  useEffect(() => {
    if (themes.length > 0) {
      void fetchInstalledStatus()
    }
    // 同时获取已安装主题列表（用于主题切换）
    void fetchInstalledThemes()
  }, [themes, fetchInstalledStatus, fetchInstalledThemes])

  // 处理主题切换
  const handleSwitchTheme = async (themeDir: string) => {
    setSwitching(themeDir)
    try {
      const res = await service.post('/hexopro/api/theme/switch', { themeDir })
      if (res.data?.success) {
        message.success(
          t['theme.switch.success'] ||
            `主题已切换到 ${themeDir}，请刷新页面查看效果`,
        )
        // 刷新已安装主题列表
        await fetchInstalledThemes()
        await fetchInstalledStatus()
        // 显示提示，建议用户刷新
        Modal.info({
          title: t['theme.switch.reloadTitle'] || '主题切换成功',
          content:
            t['theme.switch.reloadContent'] ||
            '主题已切换成功。为了看到新主题的效果，请刷新页面（按 F5 或 Ctrl+R）。',
          okText: t['theme.switch.reloadOk'] || '知道了',
        })
      }
    } catch (err: any) {
      message.error(
        err?.response?.data?.msg ||
          t['theme.switch.failed'] ||
          '切换主题失败',
      )
    } finally {
      setSwitching(null)
      setSwitchModalVisible(false)
    }
  }

  // 打开主题切换弹窗
  const openSwitchModal = () => {
    setSwitchModalVisible(true)
  }

  // 关闭主题切换弹窗
  const closeSwitchModal = () => {
    setSwitchModalVisible(false)
  }

  const handleInstall = async (themeId: string) => {
    setInstalling(themeId)
    try {
      await service.post('/hexopro/api/theme/install', { themeId })
      message.success(t['theme.install.success'] || '主题安装完成')
      await fetchInstalledStatus()
    } catch {
      message.error(t['theme.install.failed'] || '安装失败')
    } finally {
      setInstalling(null)
    }
  }

  const openConfig = (theme: BuiltinTheme) => {
    setConfigModal({
      visible: true,
      themeId: theme.id,
      themeName: theme.name,
    })
  }

  const closeConfig = () => {
    setConfigModal({
      visible: false,
      themeId: '',
      themeName: '',
    })
  }

  return (
    <div className={styles.container}>
      <Row gutter={[16, 16]}>
        <Col span={24}>
          <Title level={4}>
            <AppstoreOutlined style={{ marginRight: 8 }} />
            {t['theme.market.title'] || '主题市场'}
          </Title>
          <Text type="secondary">
            {t['theme.market.desc'] ||
              '一键安装 Hexo 主题，可视化配置主题参数'}
          </Text>
          <div style={{ marginTop: 16 }}>
            <Space>
              <Tag color="blue">
                {t['theme.currentLabel'] || '当前主题'}: {currentTheme}
              </Tag>
              {installedThemes.length > 1 && (
                <Button
                  type="primary"
                  icon={<SwapOutlined />}
                  onClick={openSwitchModal}
                >
                  {t['theme.switch.button'] || '切换主题'}
                </Button>
              )}
            </Space>
          </div>
        </Col>
      </Row>

      <Divider />

      <Spin spinning={loading}>
        <div className={styles.themeGrid}>
          {themes.map((theme) => {
            const status = statusMap[theme.id] || { installed: false, isCurrent: false }
            const isInstalling = installing === theme.id

            return (
              <Card key={theme.id} className={styles.themeCard} hoverable>
                <div className={styles.themePreview}>
                  {theme.name}
                </div>
                <div className={styles.themeInfo}>
                  <div className={styles.themeName}>{theme.name}</div>
                  <div className={styles.themeDesc}>{theme.description}</div>
                  <div className={styles.themeAuthor}>
                    {t['theme.author'] || '作者'}: {theme.author}
                  </div>
                </div>
                <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                  {!status.installed ? (
                    <Button
                      type="primary"
                      icon={<DownloadOutlined />}
                      loading={isInstalling}
                      onClick={() => handleInstall(theme.id)}
                    >
                      {t['theme.install'] || '一键安装'}
                    </Button>
                  ) : (
                    <>
                      {status.isCurrent ? (
                        <Button disabled icon={<CheckCircleOutlined />}>
                          {t['theme.current'] || '当前使用'}
                        </Button>
                      ) : (
                        <Button
                          type="primary"
                          icon={<SwapOutlined />}
                          loading={switching === theme.themeDir}
                          onClick={() => handleSwitchTheme(theme.themeDir)}
                        >
                          {t['theme.switch'] || '切换'}
                        </Button>
                      )}
                      <Button
                        icon={<SettingOutlined />}
                        onClick={() => openConfig(theme)}
                      >
                        {t['theme.config'] || '配置'}
                      </Button>
                    </>
                  )}
                </div>
              </Card>
            )
          })}
        </div>
      </Spin>

      <Drawer
        title={`${t['theme.config'] || '配置'} - ${configModal.themeName}`}
        placement="right"
        onClose={closeConfig}
        open={configModal.visible}
        width={700}
        destroyOnClose
        bodyStyle={{ padding: 0 }}
      >
        {configModal.visible && (
          <ThemeConfigPanel
            themeId={configModal.themeId}
            themeName={configModal.themeName}
            onClose={closeConfig}
          />
        )}
      </Drawer>

      {/* 主题切换弹窗 */}
      <Modal
        title={t['theme.switch.modalTitle'] || '切换主题'}
        open={switchModalVisible}
        onCancel={closeSwitchModal}
        footer={null}
        width={600}
      >
        <div style={{ padding: '16px 0' }}>
          <Text type="secondary">
            {t['theme.switch.description'] ||
              '选择一个已安装的主题进行切换。切换后需要刷新页面才能看到新主题效果。'}
          </Text>
          <div style={{ marginTop: 24 }}>
            <Space direction="vertical" style={{ width: '100%' }} size="middle">
              {installedThemes.map((theme) => (
                <Card
                  key={theme.themeDir}
                  size="small"
                  className={styles.themeSwitchCard}
                  style={{
                    borderColor:
                      theme.themeDir === currentTheme ? '#1890ff' : undefined,
                    backgroundColor:
                      theme.themeDir === currentTheme ? '#e6f7ff' : undefined,
                  }}
                >
                  <div
                    style={{
                      display: 'flex',
                      justifyContent: 'space-between',
                      alignItems: 'center',
                    }}
                  >
                    <div>
                      <Space>
                        <Text strong>{theme.name}</Text>
                        {theme.themeDir === currentTheme && (
                          <Tag color="blue">
                            {t['theme.current'] || '当前使用'}
                          </Tag>
                        )}
                        {theme.builtin && (
                          <Tag color="green">
                            {t['theme.builtin'] || '内置'}
                          </Tag>
                        )}
                      </Space>
                      <div>
                        <Text type="secondary" style={{ fontSize: 12 }}>
                          {theme.themeDir}
                        </Text>
                      </div>
                    </div>
                    {theme.themeDir !== currentTheme && (
                      <Button
                        type="primary"
                        icon={<SwapOutlined />}
                        loading={switching === theme.themeDir}
                        onClick={() => handleSwitchTheme(theme.themeDir)}
                      >
                        {t['theme.switch'] || '切换'}
                      </Button>
                    )}
                  </div>
                </Card>
              ))}
            </Space>
          </div>
        </div>
      </Modal>
    </div>
  )
}

export default ThemeMarketPage
